// Registro estruturado de falha de workflow (payload sanitizado)
const e = $json;
return { json: {
  workflow: e.workflow?.name || e.workflowName || 'desconhecido',
  execution_id: e.execution?.id || e.executionId || null,
  node: e.execution?.lastNodeExecuted || null,
  erro: e.execution?.error?.message || e.error || 'sem mensagem',
  timestamp: new Date().toISOString(),
} };
